	(19, NULL, '73FZ', 'Portal Publikasi', 'Publikasi', 'ajkhdfgbkahjfgvsdkhjgasvd', 'https://portalpublikasi.bps.go.id/', '<svg class="w-full h-full text-accent" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"></path></svg>', 2020, 'Disetujui', 'Tim IPDS', 'BPS Pusat', '2025-11-25 07:16:48'),
	(21, NULL, 'QJKE', 'EPSS', 'Sektoral', 'Website EPSS', 'https://epss.web.bps.go.id/home', 'data:image/png;base64,', 2022, 'Disetujui', 'Tim Statistik Sektoral', 'BPS Pusat', '2025-11-25 07:23:54'),
	(22, NULL, 'JXGS', 'SINERGI', 'Kinerja', 'SINERGI adalah sebuah sistem manajemen aktivitas dan kolaborasi tim yang\ndirancang untuk meningkatkan transparansi dan efisiensi kinerja pegawai di\nlingkungan kerja. Kebutuhan akan sistem terpusat menjadi latar belakang\nutama, di mana SINERGI hadir sebagai solusi untuk memfasilitasi koordinasi\nmelalui fitur kalender terpadu. Selain itu, sistem ini berfungsi sebagai\nmanajemen dokumen terpusat, memungkinkan pengguna untuk melampirkan,\nmelacak, dan mengelola dokumen penting dalam setiap aktivitas atau project.', 'https://sinergi.statsntb.id/', 'data:image/png;base64,', 2025, 'Disetujui', 'M Alif Farhan (Tim IPDS NTB)', 'BPS NTB', '2025-11-26 10:08:28'),
	(24, NULL, NULL, 'asdasdas', 'Pengolahan Data', 'dasdas', 'https://id.wikipedia.org/wiki/Nusa_Tenggara_Barat', '<svg class="w-full h-full text-accent" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"></path></svg>', 2025, 'Menunggu Persetujuan', 'askjdbajkshbdas', 'adasd', '2025-11-26 10:12:46');

-- Dumping structure for table halo_kaka_db.applications
CREATE TABLE IF NOT EXISTS `applications` (
  `id_app` varchar(50) NOT NULL DEFAULT 'AUTO_INCREMENT',
  `nama` varchar(255) NOT NULL,
  `kategori` varchar(100) DEFAULT NULL,
  `penjelasan` text,
  `link` varchar(2048) NOT NULL,
  `logo` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `tahun_buat` int DEFAULT NULL,
  `status_aplikasi` enum('Aktif','Tidak Aktif','Beta') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'Aktif',
  `narahubung` varchar(255) DEFAULT NULL,
  `developer` varchar(255) DEFAULT NULL,
  `flag_view` tinyint(1) NOT NULL DEFAULT '1',
  `jumlah_pengunjung` int NOT NULL DEFAULT '0',
  `timestamp_buat` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
