) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Dumping data for table halo_kaka_db.applications: ~46 rows (approximately)
INSERT INTO `applications` (`id_app`, `nama`, `kategori`, `penjelasan`, `link`, `logo`, `tahun_buat`, `status_aplikasi`, `narahubung`, `developer`, `flag_view`, `jumlah_pengunjung`, `timestamp_buat`, `updated_at`) VALUES
	('10', 'Jaringan Dokumentasi dan Informasi Hukum (JDIH)', 'Hukum', 'Jaringan Dokumentasi dan Informasi Hukum atau disingkat JDIH adalah wadah pendayagunaan bersama atas dokumen hukum secara tertib, terpadu, dan berkesinambungan, serta merupakan sarana pemberian pelayanan informasi hukum secara lengkap, akurat, mudah, dan cepat.', 'https://jdih.web.bps.go.id/public/', 'data:image/png;base64,', 2022, 'Aktif', 'SDM', 'BPS Pusat', 1, 1, '2025-11-16 09:59:19', '2025-11-26 04:07:26'),
	('11', 'KipApp', 'Kinerja', 'Aplikasi manajemen kinerja pegawai BPS. Digunakan untuk penyusunan SKP, penilaian kinerja, dll.', 'https://kipapp.bps.go.id/#/home', 'data:image/png;base64,', 2022, 'Aktif', 'Bagian Umum', 'BPS Pusat', 1, 105001, '2025-11-16 09:59:20', '2025-11-25 08:40:46'),
	('12', 'KRISNA', 'Anggaran', 'Aplikasi KRISNA adalah Sistem perencanaan, penganggaran, dansistem informasi kinerja merupakan tiga fondasi utama mengawal berjalannya anggaran negara secara akuntabel. Melalui KRISNA 3.0,setiap perencanaan program dan anggaran akan disusun secara transparan dan akuntabel. Dalam pelaksanaan penggunaan anggaran akan diawasi ketat melalui Sistem Akuntabilitas Kinerja Instansi Pemerintah (SAKIP).', 'https://krisna.systems/auth/portal', 'data:image/png;base64,', 2022, 'Aktif', 'Bagian Umum', 'Bappenas', 1, 0, '2025-11-16 09:59:21', '2025-11-25 08:40:30'),
	('13', 'LPSE', 'Pengadaan', 'platform yang digunakan untuk melakukan pengadaan barang dan jasa secara elektronik oleh instansi pemerintah di Indonesia.', 'https://spse.inaproc.id/', 'data:image/webp;base64,', 2022, 'Aktif', 'Keuangan', 'LKPP', 1, 0, '2025-11-16 09:59:22', '2025-11-26 04:06:51'),
	('14', 'Manajemen Mitra', 'Administrasi', 'Aplikasi Pengelolaan Mitra Kegiatan Sensus dan Survei Badan Pusat Statistik', 'https://manajemen-mitra.bps.go.id/', 'data:image/png;base64,', 2022, 'Aktif', 'IPDS', 'BPS Pusat', 1, 1, '2025-11-16 09:59:23', '2025-11-26 04:06:26'),
	('15', 'Masterplan', 'Perencanaan', 'Aplikasi yang digunakan untuk merencanakan, mengelola, dan memantau kegiatan survei atau sensus yang dilakukan oleh BPS.', 'https://https/iplan.bps.go.id/masterplan', '<svg class="w-full h-full text-accent" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"></path></svg>', 2022, 'Aktif', 'Binagram', 'BPS Pusat', 1, 1, '2025-11-16 09:59:24', '2025-11-26 04:06:14'),
	('16', 'PPID', 'Publikasi dan Diseminasi', 'PPID BPS (Pejabat Pengelola Informasi dan Dokumentasi Badan Pusat Statistik), yang merupakan platform resmi untuk mengakses informasi publik terkait kegiatan dan data yang dikelola oleh Badan Pusat Statistik (BPS) Indonesia.', 'https://ppid.bps.go.id/', 'data:image/png;base64,', 2022, 'Aktif', 'Binagram', 'BPS Pusat', 1, 1, '2025-11-16 09:59:25', '2025-11-26 04:06:03'),
	('17', 'PPID Dashboard', 'Publikasi dan Diseminasi', 'aplikasi Dashboard PPID yang mengatur konten dan isian yang ada pada website https://ppid.bps.go.id/', 'https://ppid.bps.go.id/dashboard/', 'data:image/svg+xml;base64,', 2022, 'Aktif', 'Binagram dan IPDS', 'BPS Pusat', 1, 1, '2025-11-16 09:59:26', '2025-11-26 04:05:41'),
	('18', 'Presensi BPS', 'Administrasi', 'Aplikasi presensi pegawai Badan Pusat Statistik', 'https://presensi.bps.go.id/support', 'data:image/webp;base64,', 2022, 'Aktif', 'SDM', 'BPS Pusat', 1, 1, '2025-11-16 09:59:27', '2025-11-26 04:04:54'),
	('19', 'SAKTI', 'Keuangan', 'SAKTI (Sistem Aplikasi Keuangan Tingkat Instansi) adalah aplikasi terintegrasi berbasis web yang dikembangkan oleh Kementerian Keuangan (Kemenkeu) melalui Direktorat Jenderal Perbendaharaan (DJPb) untuk mengelola seluruh siklus keuangan negara pada tingkat satuan kerja pemerintah. Aplikasi ini dirancang untuk meningkatkan efisiensi, transparansi, dan akuntabilitas dalam pengelolaan keuangan negara.', 'https://sakti.kemenkeu.go.id/', 'data:image/png;base64,', 2022, 'Aktif', 'Keuangan', 'Kementrian Keuangan', 1, 2000, '2025-11-16 09:59:28', '2025-11-25 08:40:00'),
	('20', 'MonSakti', 'Keuangan', 'Platform monitoring, pengendalian, pengawasan, rekonsiliasi, pelaporan, dan evaluasi transaksi keuangan negara', 'https://monsakti.kemenkeu.go.id/', 'data:image/png;base64,', 2022, 'Aktif', 'Keuangan', 'Kementrian Keuangan', 1, 1, '2025-11-16 09:59:29', '2025-11-26 04:04:18'),
	('21', 'SEKAR', 'Administrasi', 'SEKAR (Sistem Entri Dan Kelola Arsip)', 'https://sekar.bps.go.id/', '<svg class="w-full h-full text-accent" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"></path></svg>', 2022, 'Tidak Aktif', 'BMN', 'BPS Pusat', 1, 1, '2025-11-16 09:59:30', '2025-11-26 04:04:03'),
	('22', 'SHBJ', 'Pengumpulan Data', 'Aplikasi untuk menginput data hasil SHBJ (Survei Harga Barang dan Jasa)', 'https://shbj.bps.go.id/', '<svg class="w-full h-full text-accent" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"></path></svg>', 2022, 'Tidak Aktif', 'Binagram', 'BPS Pusat', 1, 0, '2025-11-16 09:59:31', '2025-11-26 04:03:45'),
	('23', 'Si Intip Mitra ATR BPN', 'Administrasi', 'Aplikasi untuk mengakses layanan ATR/BPN', 'https://mitra.atrbpn.go.id/', 'data:image/png;base64,', 2022, 'Aktif', 'Bagian Umum', 'BPS Pusat', 1, 1, '2025-11-16 09:59:32', '2025-11-26 08:51:07'),
	('24', 'SIIMUT', 'Administrasi', 'Sistem mutasi pegawai di BPS (pengajuan mutasi jabatan atau pindah).', 'https://sdm.bps.go.id/siimut/web/', 'data:image/png;base64,', 2022, 'Aktif', 'SDM', 'BPS Pusat', 1, 1201, '2025-11-16 09:59:33', '2025-11-26 04:03:08'),
	('25', 'SIJAFUNG', 'Administrasi', 'Aplikasi tentang jabatan fungsional yang dibina oleh Badan Pusat Statistik (Statistisi dan Pranata Komputer)', 'https://jafung.bps.go.id/', 'data:image/png;base64,', 2022, 'Aktif', 'SDM', 'BPS Pusat', 1, 1, '2025-11-16 09:59:34', '2025-11-26 04:02:39'),
	('26', 'SIMAN', 'Administrasi', 'Aplikasi pengelolaan BMN secara umum', 'https://siman.kemenkeu.go.id/login', 'data:image/png;base64,', 2022, 'Aktif', 'BMN', 'Kementrian Keuangan', 1, 1, '2025-11-16 09:59:35', '2025-11-26 04:02:18'),
	('27', 'SINERGI', 'Kinerja', 'Aplikasi Sinergi merupakan platform terintegrasi untuk penyelenggaraan Sistem Akuntabilitas Kinerja Instansi Pemerintah (SAKIP) di lingkungan BPS. Aplikasi ini berfungsi secara bertahap dan saat ini sedang dalam pengembangan modul evaluasi.', 'https://sinergi.web.bps.go.id/', 'data:image/png;base64,', 2022, 'Aktif', 'Binagram', 'BPS Pusat', 1, 1, '2025-11-16 09:59:11', '2025-11-26 04:09:55');
INSERT INTO `applications` (`id_app`, `nama`, `kategori`, `penjelasan`, `link`, `logo`, `tahun_buat`, `status_aplikasi`, `narahubung`, `developer`, `flag_view`, `jumlah_pengunjung`, `timestamp_buat`, `updated_at`) VALUES
	('28', 'SIMPEG', 'Administrasi', 'Sistem Informasi Manajemen Kepegawaian BPS. Digunakan untuk manajemen data pegawai BPS.', 'https://simpeg.bps.go.id/data/', 'data:image/png;base64,', 2022, 'Aktif', 'SDM', 'BPS Pusat', 1, 1, '2025-11-16 09:59:08', '2025-11-26 04:10:06'),
	('29', 'SIPECUT', 'Administrasi', 'Sistem Informasi Pengajuan Cuti pegawai di lingkungan BPS.', 'https://sipecut.bps.go.id/', 'data:image/svg+xml;base64,', 2022, 'Aktif', 'SDM', 'BPS Pusat', 1, 0, '2025-11-16 09:59:07', '2025-11-26 04:11:07'),
	('3', 'BackOffice Selindo', 'Administrasi', 'BackOffice Selindo merupakan Sistem Informasi Manajemen yang terintegrasi dalam menyertai siklus APBN di lingkungan BPS.', 'https://backoffice.bps.go.id/', 'data:image/png;base64,', 2022, 'Aktif', 'Bagian Umum', 'BPS Pusat', 1, 1200002, '2025-11-16 09:59:12', '2025-11-26 09:42:59'),
	('30', 'Sipmanner', 'Kinerja', 'Sistem Pengelolaan Manajemen Perubahan yang digunakan oleh para agen perubahan atau CC.', 'https://manner.web.bps.go.id/sipmanner/', 'data:image/png;base64,', 2022, 'Aktif', 'Binagram dan CAN', 'BPS Pusat', 1, 0, '2025-11-16 09:59:06', '2025-11-26 04:11:55'),
	('31', 'SiRUP', 'Keuangan', 'Aplikasi Sistem Informasi Rencana Umum Pengadaan (SIRUP) adalah aplikasi yang berbasis Website (Web based) yang fungsinya sebagai sarana atau alat untuk mengumumkan Rencana Umum Pengadaan (RUP)', 'https://sirup.lkpp.go.id/sirup/ro', 'data:image/png;base64,', 2022, 'Aktif', 'Keuangan', 'LKPP', 1, 0, '2025-11-16 09:59:04', '2025-11-26 04:13:06'),
	('32', 'Sivera', 'Keuangan', 'SIVERA (Sistem Informasi Verifikasi dan Realisasi Anggaran)', 'http://sivera.bps.go.id/', '<svg class="w-full h-full text-accent" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"></path></svg>', 2022, 'Tidak Aktif', 'Keuangan', 'BPS Pusat', 1, 1, '2025-11-16 09:59:03', '2025-11-26 04:13:13'),
	('33', 'SMART', 'Perencanaan', 'SMART (Sistem Monitoring dan Evaluasi Kinerja Terpadu Kementerian Keuangan) adalah aplikasi berbasis web yang dibangun guna memudahkan satuan kerja dalam monitoring dan evaluasi pelaksanaan anggaran', 'https://monev.kemenkeu.go.id/', '<svg class="w-full h-full text-accent" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"></path></svg>', 2022, 'Aktif', 'Binagram', 'BPS Pusat', 1, 1, '2025-11-16 09:59:01', '2025-11-26 04:13:40');
INSERT INTO `applications` (`id_app`, `nama`, `kategori`, `penjelasan`, `link`, `logo`, `tahun_buat`, `status_aplikasi`, `narahubung`, `developer`, `flag_view`, `jumlah_pengunjung`, `timestamp_buat`, `updated_at`) VALUES
	('34', 'SRIKANDI', 'Administrasi', 'Srikandi adalah platform Sistem Registrasi Kearsipan Digital yang digunakan untuk mendukung pengelolaan arsip secara elektronik di Indonesia. Platform ini memungkinkan instansi pemerintah dan lembaga lainnya untuk mengelola arsip mereka dalam format digital, yang mempermudah penyimpanan, pengelolaan, serta akses terhadap dokumen dan arsip penting.', 'https://srikandi.arsip.go.id/', 'data:image/png;base64,', 2022, 'Aktif', 'Arsiparis', 'Arsip Nasional RI', 1, 1, '2025-11-16 09:58:58', '2025-11-26 04:13:52'),
	('35', 'TK Online', 'Administrasi', 'Aplikasi input kinerja pegawai BPS', 'https://tkonline.bps.go.id/bye.aspx', 'data:image/png;base64,', 2022, 'Aktif', 'SDM', 'BPS Pusat', 1, 1, '2025-11-16 09:58:57', '2025-11-26 04:14:04'),
	('36', 'tokodaring.lkpp.go.id', 'Pengadaan', 'Toko Daring LKPP adalah sebuah marketplace (pasar daring) bagi Penyedia Barang/Jasa Pemerintah untuk melakukan transaksi pengadaan barang dan jasa secara elektronik.', 'https://tokodaring.lkpp.go.id/', 'data:image/webp;base64,', 2022, 'Aktif', 'Keuangan', 'LKPP', 1, 1, '2025-11-16 09:58:56', '2025-11-26 04:14:21'),
	('37', 'Silastik', 'Publikasi dan Diseminasi', 'Sistem Informasi Layanan Statistik adalah Sistem Informasi yang membantu komunikasi antara pengguna data dan operator BPS dalam melakukan transaksi pembelian atau konsultasi data.', 'https://silastik.bps.go.id/v3/index.php/site/login/', 'data:image/png;base64,', 2022, 'Aktif', 'IPDS', 'BPS Pusat', 1, 1, '2025-11-16 09:58:48', '2025-11-26 04:14:30'),
	('38', 'Indah (Indonesia Data Hub)', 'Sektoral', 'Indonesia Data Hub (INDAH) merupakan one stop collaboration platform yang bertujuan untuk meningkatkan literasi data dan value of statistics serta mendukung interoperabilitas data dan kolaborasi eksplorasi terhadap data.', 'https://indah.bps.go.id/', 'data:image/png;base64,', 2022, 'Aktif', 'IPDS', 'BPS Pusat', 1, 0, '2025-11-16 09:59:59', '2025-11-25 08:39:40'),
	('39', 'PST Online', 'Publikasi dan Diseminasi', 'merupakan aplikasi Pelayanan Statistik Terpadu BPS RI.', 'https://pst.bps.go.id/', 'data:image/svg+xml;base64,', 2022, 'Aktif', 'IPDS', 'BPS Pusat', 1, 1, '2025-11-16 09:59:58', '2025-11-26 04:00:03');
INSERT INTO `applications` (`id_app`, `nama`, `kategori`, `penjelasan`, `link`, `logo`, `tahun_buat`, `status_aplikasi`, `narahubung`, `developer`, `flag_view`, `jumlah_pengunjung`, `timestamp_buat`, `updated_at`) VALUES
	('4', 'E-monev', 'Kinerja', 'E-Monev adalah aplikasi berbasis online sebagai media pelaporan data realisasi hasil pemantauan pelaksanaan rencana pembangunan (dalam hal ini Renja-K/L).', 'https://e-monev.bappenas.go.id/', 'data:image/png;base64,', 2022, 'Aktif', 'Binagram', 'Bappenas', 1, 1, '2025-11-16 09:59:13', '2025-11-26 04:09:42'),
	('40', 'MFD Online', 'Pengumpulan Data', 'Sistem pemutakhiran Master Wilayah dan Wilayah Kerja Statistik. Memelihara hierarki perubahan wilayah yang dibutuhkan untuk bridging wilayah', 'https://frs.bps.go.id/area/login', 'data:image/png;base64,', 2022, 'Aktif', 'IPDS', 'BPS Pusat', 1, 1, '2025-11-16 09:59:57', '2025-11-26 04:00:25'),
	('41', 'SIG BPS', 'Visualisasi', 'Sistem Informasi Geospasial-BPS. Situs ini bertujuan untuk menyajikan kepada publik berbagai informasi yang terkait dengan kerangka wilayah kerja statistik, peta, dan data.', 'https://sig.bps.go.id/', 'data:image/png;base64,', 2022, 'Aktif', 'IPDS', 'BPS Pusat', 1, 1, '2025-11-16 09:59:56', '2025-11-26 04:57:48'),
	('42', 'E-TTD', 'Administrasi', 'E-TTD BPS merupakan aplikasi untuk mengelola tandatangan elektronik (TTE). Aplikasi ini merupakan hasil dari Kerjasama dengan BSrE, BSSN. Dimana sertifikat elektronik yang dipakai diterbitkan oleh BSrE. Setiap dokumen yang ditandatangani harus melalui proses otentikasi passphrase melalui server BSrE.', 'https://ettd.bps.go.id/', 'data:image/png;base64,', 2022, 'Aktif', 'Bagian Umum', 'BPS Pusat', 1, 3, '2025-11-16 09:59:55', '2025-11-30 12:30:20');
INSERT INTO `applications` (`id_app`, `nama`, `kategori`, `penjelasan`, `link`, `logo`, `tahun_buat`, `status_aplikasi`, `narahubung`, `developer`, `flag_view`, `jumlah_pengunjung`, `timestamp_buat`, `updated_at`) VALUES
	('43', 'Harmonis', 'Administrasi', 'HARMONIS (Human Resource Management and Organization Information System) adalah sistem informasi kepegawaian terpadu yang dikembangkan khusus untuk Badan Pusat Statistik (BPS).', 'https://harmonis.web.bps.go.id/', 'data:image/png;base64,', 2022, 'Aktif', 'SDM', 'BPS Pusat', 1, 1, '2025-11-16 09:59:54', '2025-11-26 04:01:08'),
	('44', 'SIMDIKLAT', 'Pendidikan dan Pelatihan', 'Sistem Informasi Manajemen Pendidikan dan Pelatihan Pusdiklat Badan Pusat Statistik', 'https://simdiklat.web.bps.go.id/', 'data:image/png;base64,', 2022, 'Aktif', 'SDM', 'BPS Pusat', 1, 1, '2025-11-16 09:59:53', '2025-11-26 04:01:39'),
	('45', 'eWARKOP', 'Pendidikan dan Pelatihan', 'e-Warkop merupakan platform yang menyediakan berbagai menu pembelajaran yang dapat dipilih oleh pengguna.', 'https://lms.bps.go.id/', 'data:image/png;base64,', 2022, 'Aktif', 'SDM', 'BPS Pusat', 1, 8700, '2025-11-16 09:59:52', '2025-11-25 08:47:09'),
	('46', 'Gojags', 'Pendidikan dan Pelatihan', 'GOJAGS merupakan tempat Administrasi bangkom dikumpulkan dan dikelola, sebagai pelengkap LMS yang merupakan Ruang Kelas kegiatan belajar secara virtual.', 'https://gojags.web.bps.go.id/', 'data:image/png;base64,', 2022, 'Aktif', 'SDM', 'BPS Pusat', 1, 12501, '2025-11-16 09:59:51', '2025-11-26 04:01:57'),
	('47', 'App ROpi', 'Pengumpulan Data', 'af adasd', 'https://id.wikipedia.org/wiki/Nusa_Tenggara_Barat', '', 2005, 'Aktif', 'asd', 'asdasd', 0, 1, '2025-11-16 14:38:05', '2025-11-24 15:44:10');
INSERT INTO `applications` (`id_app`, `nama`, `kategori`, `penjelasan`, `link`, `logo`, `tahun_buat`, `status_aplikasi`, `narahubung`, `developer`, `flag_view`, `jumlah_pengunjung`, `timestamp_buat`, `updated_at`) VALUES
	('5', 'e-SAKIP', 'Kinerja', 'e-SAKIP atau ESR Menpan merupakan aplikasi untuk mengupload dokumen kinerja yang dibutuhkan dari satuan kerja', 'https://esr.menpan.go.id/', 'data:image/jpeg;base64,', 2022, 'Aktif', 'Binagram', 'Menpan RB', 1, 1, '2025-11-16 09:59:14', '2025-11-26 04:09:29');
INSERT INTO `applications` (`id_app`, `nama`, `kategori`, `penjelasan`, `link`, `logo`, `tahun_buat`, `status_aplikasi`, `narahubung`, `developer`, `flag_view`, `jumlah_pengunjung`, `timestamp_buat`, `updated_at`) VALUES
	('6', 'INAPROC (ecatalouge)', 'Pengadaan', 'INAPROC (ecatoluge) Katalog Elektronik Versi 6, atau yang disebut “Katalog Elektronik”, adalah suatu bagian dari ekosistem Platform Pengadaan Nasional yang dimiliki oleh LKPP dan dikelola bersama Telkom yang memiliki fungsi sebagai platform yang digunakan oleh Kementerian, Lembaga setingkat Kementerian, dan/atau serta Pemerintah Daerah dalam pelaksanaan pengadaan barang dan jasa untuk dana yang bersumber dari APBN dan/atau APBD melalui metode E-Purchasing.', 'https://katalog.inaproc.id/', 'data:image/webp;base64,', 2022, 'Aktif', 'Keuangan', 'LKPP', 1, 1, '2025-11-16 09:59:15', '2025-11-26 04:09:09'),
	('7', 'Fasih', 'Pengolahan Data', 'FASIH adalah aplikasi Survei dan Sensus milik Badan Pusat Statistik. FASIH dapat memuat berbagai Kuesioner Survei dan Sensus.', 'https://fasih-sm.bps.go.id/', 'data:image/png;base64,', 2022, 'Aktif', 'IPDS', 'BPS Pusat', 1, 1, '2025-11-16 09:59:16', '2025-11-26 04:08:56'),
	('73FZ', 'Portal Publikasi', 'Publikasi', 'ajkhdfgbkahjfgvsdkhjgasvd', 'https://portalpublikasi.bps.go.id/', 'data:image/png;base64,', 2020, 'Aktif', 'Tim IPDS', 'BPS Pusat', 1, 1, '2025-11-25 07:20:59', '2025-11-26 03:59:33'),
	('8', 'Fasih (dashboard)', 'Visualisasi', 'merupakan bagian dari FASIH yang berfungsi untuk menampilkan visualisasi data hasil pelaksanaan kegiatan yang menggunakan aplikasi FASIH', 'https://fasih-dashboard.bps.go.id/', 'data:image/png;base64,', 2022, 'Aktif', 'IPDS', 'BPS Pusat', 1, 0, '2025-11-16 09:59:17', '2025-11-26 04:08:47'),
	('9', 'IPLAN', 'Kinerja', 'Sistem informasi yang digunakan BPS untuk menghimpun usulan aktivitas yang diajukan oleh unit kerja Eselon II di BPS RI, Politeknik Statistika STIS, dan Pusdiklat BPS dalam rangka penyusunan RKA.', 'https://rencana.web.bps.go.id/app/', 'data:image/png;base64,', 2022, 'Aktif', 'Binagram', 'BPS Pusat', 1, 1, '2025-11-16 09:59:18', '2025-11-26 04:07:52'),
	('E9C0', 'pengguna1 app', 'Kemana saja', 'sdfsadf', 'https://id.wikipedia.org/wiki/Nusa_Tenggara_Barat', '', 2001, 'Aktif', 'sdfsdf', 'sfsdfs', 0, 0, '2025-11-16 15:57:02', '2025-11-24 14:22:02'),
	('JXGS', 'SINERGI', 'Kinerja', 'SINERGI adalah sebuah sistem manajemen aktivitas dan kolaborasi tim yang\ndirancang untuk meningkatkan transparansi dan efisiensi kinerja pegawai di\nlingkungan kerja. Kebutuhan akan sistem terpusat menjadi latar belakang\nutama, di mana SINERGI hadir sebagai solusi untuk memfasilitasi koordinasi\nmelalui fitur kalender terpadu. Selain itu, sistem ini berfungsi sebagai\nmanajemen dokumen terpusat, memungkinkan pengguna untuk melampirkan,\nmelacak, dan mengelola dokumen penting dalam setiap aktivitas atau project.', 'https://sinergi.statsntb.id/', 'data:image/png;base64,', 2025, 'Aktif', 'M Alif Farhan (Tim IPDS NTB)', 'BPS NTB', 1, 20200, '2025-11-26 10:09:46', '2025-11-26 10:27:43'),
	('QJKE', 'EPSS', 'Sektoral', 'Website EPSS (Evaluasi Penyelenggaraan Statistik Sektoral) mengambarkan outcome pembinaan statistik sektoral untuk meningkatkan layanan statistik BPS lebih lanjut.', 'https://epss.web.bps.go.id/home', 'data:image/png;base64,', 2022, 'Aktif', 'Tim Statistik Sektoral', 'BPS Pusat', 1, 1, '2025-11-25 07:24:10', '2025-11-26 09:11:35');

